import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome120 {
    data class Success(val payload: String) : Outcome120()
    data object Failure : Outcome120()
}

fun describe120(outcome: Outcome120): String = when (outcome) {
    is Outcome120.Success -> outcome.payload
    Outcome120.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked121(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
class Counter122 {
    var current: Int by Delegates.observable(78) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
